+/** The best supported language for an Accept-Language header value, else `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  if (typeof header !== "string") return fallback;
+  const ranges = [];
+  header.split(",").forEach((part, index) => {
+    const [range, ...params] = part.trim().split(";").map((x) => x.trim());
+    if (!range) return;
+    let q = 1;
+    for (const param of params) {
+      const m = /^q\s*=\s*([0-9.]+)$/i.exec(param);
+      if (m) q = /^(0(\.\d{0,3})?|1(\.0{0,3})?)$/.test(m[1]) ? Number(m[1]) : -1;
+    }
+    if (q > 0) ranges.push({ lang: range.toLowerCase().split("-")[0], q, index });
+  });
+  ranges.sort((a, b) => b.q - a.q || a.index - b.index);
+  return ranges.find((r) => r.lang in MESSAGES)?.lang ?? fallback;
+}
